#!/usr/bin/env node
// Generate the minipc stage's image-dependent parts from the ACTUAL image build (image-kit/image-build.json, runtime.json):
//   activation/minipc/pins.ps1                      $ImageSha, $ImageFile, $RuntimeJsonSha, $RuntimeId
//   activation/minipc/settings/shield-direct-manager.cmd   ENCLAVE_SHIELD_DIRECT=1 + the image path, sha256, runtime identity file
//   activation/minipc/settings/shield-direct-node.cmd      ENCLAVE_ISOLATION_DIRECT_RUNTIME_ID / _IMAGE_SHA256 (the node's own pins)
//   activation/minipc/image/{vbs-linux-candidate.bin, runtime.json}
// and the Shield policy that admits exactly the new (VBS digest, RuntimeID) pair with the repository's pinned TPM roots, for the
// replicas and owner-name responders. RuntimeID is derived with isolation/contract/runtime.mjs (never typed in).
//   node make-minipc-stage.mjs <release-prep dir>
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';

const R = path.resolve(process.argv[2] || '.');
const sha = (b) => createHash('sha256').update(b).digest('hex');
const kit = path.join(R, 'image-kit'), M = path.join(R, 'activation/minipc');
const b = JSON.parse(fs.readFileSync(path.join(kit, 'image-build.json'), 'utf8'));
const img = fs.readFileSync(path.join(b.kept, 'vbs-linux-candidate.bin'));
if (sha(img) !== b.candidate.binSha) throw new Error('the kept image is not the built candidate');
const runtimeJson = fs.readFileSync(path.join(kit, 'runtime.json'));
const {runtimeId, validateRuntimeIdentity} = await import(pathToFileURL(path.join(R, 'tree/isolation/contract/runtime.mjs')).href);
const runtime = JSON.parse(runtimeJson);
const fault = validateRuntimeIdentity?.(runtime); if (fault) throw new Error('runtime.json: ' + fault);
const rid = Buffer.from(runtimeId(runtime)).toString('hex'), digest = String(b.candidate.digest).toLowerCase(), imageSha = b.candidate.binSha;
fs.mkdirSync(path.join(M, 'image'), {recursive: true}); fs.mkdirSync(path.join(M, 'settings'), {recursive: true});
fs.writeFileSync(path.join(M, 'image/vbs-linux-candidate.bin'), img); fs.writeFileSync(path.join(M, 'image/runtime.json'), runtimeJson);
fs.writeFileSync(path.join(M, 'pins.ps1'), `# generated by make-minipc-stage.mjs from the image build (do not edit)\n$ImageSha = '${imageSha}'\n$ImageFile = 'vbs-linux-candidate.bin'\n$RuntimeJsonSha = '${sha(runtimeJson)}'\n$RuntimeId = '${rid}'\n$VbsDigest = '${digest}'\n`);
const dir = `%ProgramData%\\Enclave\\shield-direct\\image-${imageSha.slice(0, 12)}`;
fs.writeFileSync(path.join(M, 'settings/shield-direct-manager.cmd'), ['@echo off', 'rem Shield-direct image (certificate-shield-appzone-20261021): public pins only', 'set ENCLAVE_SHIELD_DIRECT=1',
  `set ENCLAVE_SHIELD_DIRECT_IGVM=${dir}\\vbs-linux-candidate.bin`, `set ENCLAVE_SHIELD_DIRECT_IGVM_SHA256=${imageSha}`, `set ENCLAVE_SHIELD_DIRECT_RUNTIME_IDENTITY=${dir}\\runtime.json`, ''].join('\r\n'));
fs.writeFileSync(path.join(M, 'settings/shield-direct-node.cmd'), ['@echo off', 'rem the node\'s own Shield-direct pins (certificate-shield-appzone-20261021)', `set ENCLAVE_ISOLATION_DIRECT_RUNTIME_ID=${rid}`,
  `set ENCLAVE_ISOLATION_DIRECT_IMAGE_SHA256=${imageSha}`, ''].join('\r\n'));
// the Shield policy for replicas / responders: the repository's pinned AMD fTPM roots and ONLY the new pair
const roots = fs.readFileSync(path.join(R, 'tree/relay/fixtures/tpm-roots.pem'), 'utf8');
const policy = {schema: 'enclave-shield-app-policy/1', ekRoots: roots, platforms: 'attested', images: [{measurement: digest, runtimeId: rid}]};
const {validateShieldResponderPolicy} = await import(pathToFileURL(path.join(R, 'tree/relay/dns-challenge-shield.mjs')).href);
validateShieldResponderPolicy(policy);
const pf = path.join(R, 'activation', `shield-app-policy.${digest.slice(0, 12)}.json`); fs.writeFileSync(pf, JSON.stringify(policy, null, 1) + '\n');
const out = {imageSha256: imageSha, imageBytes: img.length, vbsDigest: digest, runtimeId: rid, runtimeJsonSha256: sha(runtimeJson), policyFile: path.relative(R, pf),
  policySha256: sha(fs.readFileSync(pf)), debugTwinDigest: String(b.debugTwin.digest).toLowerCase(), pinsSha256: sha(fs.readFileSync(path.join(M, 'pins.ps1'))),
  managerSettingsSha256: sha(fs.readFileSync(path.join(M, 'settings/shield-direct-manager.cmd'))), nodeSettingsSha256: sha(fs.readFileSync(path.join(M, 'settings/shield-direct-node.cmd')))};
fs.writeFileSync(path.join(R, 'activation/minipc-stage.json'), JSON.stringify(out, null, 1) + '\n');
console.log(JSON.stringify(out));
